mapper.select:
select distinct t.SAP ,t.EMBRYO_CODE,t.JOB_TYPE,t.Machine_code,t.machine_name  from
(

    tsm.DEL_FLAG='0'  and tsml.PROCEDURE_CODE='1' and tsml.del_flag='0' and cmi.del_flag='0'
     and tsml.machine_code = #{cxMachineCode}
     and tsm.SAP = #{sapCode}
     and tsm.EMBRYO_CODE = #{embryoCode}
     and tsm.job_type = #{jobType}

union all
select distinct tcsm.SAP_CODE SAP,tcsm.EMBRYO_CODE,tcsm.JOB_TYPE,tcsm.Machine_code,cmi.machine_name  from  T_CX_SPECIFY_MACHINE tcsm
left join t_cx_machine_info cmi
  on tcsm.machine_code=cmi.machine_code

    tcsm.DEL_FLAG='0' and cmi.DEL_FLAG='0'
     and tcsm.machine_code = #{cxMachineCode}
     and tcsm.SAP_CODE = #{sapCode}
     and tcsm.EMBRYO_CODE = #{embryoCode}
     and tcsm.job_type = #{jobType}

)t
